CREATE TABLE audit_events (
  event_id TEXT PRIMARY KEY NOT NULL,
  request_id TEXT,
  trace_id TEXT,
  actor_json JSONB NOT NULL
    CHECK (jsonb_typeof(actor_json) = 'object'),
  action TEXT NOT NULL
    CHECK (
      char_length(action) BETWEEN 1 AND 128
      AND action ~ '^[a-z][a-z0-9_.]*$'
    ),
  target_type TEXT NOT NULL
    CHECK (char_length(btrim(target_type)) >= 1),
  target_id TEXT NOT NULL,
  before_json JSONB NOT NULL
    CHECK (jsonb_typeof(before_json) = 'object'),
  after_json JSONB NOT NULL
    CHECK (jsonb_typeof(after_json) = 'object'),
  reason TEXT
    CHECK (reason IS NULL OR char_length(reason) <= 2048),
  ip TEXT,
  user_agent TEXT
    CHECK (user_agent IS NULL OR char_length(user_agent) <= 1024),
  occurred_at TIMESTAMPTZ NOT NULL
);

CREATE INDEX idx_audit_events_action_occurred_at
  ON audit_events(action, occurred_at);

CREATE INDEX idx_audit_events_target_occurred_at
  ON audit_events(target_type, target_id, occurred_at);

CREATE FUNCTION neon_w09_d1_03_reject_audit_event_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
BEGIN
  RAISE EXCEPTION 'AUDIT_EVENT_IMMUTABLE'
    USING ERRCODE = '55000';
END;
$$;

CREATE TRIGGER trg_neon_w09_audit_events_immutable_update_delete
BEFORE UPDATE OR DELETE ON audit_events
FOR EACH ROW
EXECUTE FUNCTION neon_w09_d1_03_reject_audit_event_mutation();

CREATE TRIGGER trg_neon_w09_audit_events_immutable_truncate
BEFORE TRUNCATE ON audit_events
FOR EACH STATEMENT
EXECUTE FUNCTION neon_w09_d1_03_reject_audit_event_mutation();

COMMENT ON TABLE audit_events IS
  'W09-owned immutable D1-03 AuditEvent persistence. Cross-domain references are opaque IDs; no cross-domain foreign keys.';

CREATE TABLE notification_push_endpoints (
  endpoint_id TEXT PRIMARY KEY NOT NULL,
  installation_id TEXT NOT NULL UNIQUE,
  owner_user_id TEXT NOT NULL,
  provider TEXT NOT NULL
    CHECK (provider = 'expo'),
  platform TEXT NOT NULL
    CHECK (platform IN ('ios', 'android')),
  push_token TEXT,
  permission_status TEXT NOT NULL
    CHECK (permission_status IN ('granted', 'denied', 'undetermined')),
  app_version TEXT
    CHECK (app_version IS NULL OR char_length(app_version) BETWEEN 1 AND 64),
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  last_seen_at TIMESTAMPTZ NOT NULL,
  CHECK (
    (permission_status = 'granted' AND push_token IS NOT NULL)
    OR
    (permission_status IN ('denied', 'undetermined') AND push_token IS NULL)
  ),
  CHECK (push_token IS NULL OR char_length(push_token) BETWEEN 20 AND 512)
);

CREATE UNIQUE INDEX uq_notification_push_endpoints_provider_token
  ON notification_push_endpoints(provider, push_token)
  WHERE push_token IS NOT NULL;

CREATE INDEX ix_notification_push_endpoints_owner_status
  ON notification_push_endpoints(owner_user_id, permission_status, updated_at);

COMMENT ON TABLE notification_push_endpoints IS
  'W09-owned D1-03 Expo endpoint registry. W05 has only the explicit T14 scoped delegation; no user/identity foreign key is permitted.';
